// Package server is the tifa runtime. Only code generated by the tifa CLI should import it.
package server

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"runtime/debug"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/liustack/tifa"
	"github.com/liustack/tifa/internal/config"
	"github.com/liustack/tifa/internal/core"
)

// Hooks are the optional functions of the application's hooks.go.
type Hooks struct {
	OnStart    func() error
	OnShutdown func(ctx context.Context) error
	OnRequest  func(c *tifa.Ctx) error
	OnError    func(c *tifa.Ctx, err error) tifa.Error
}

// Renderer draws whole-page HTML. Without one, whole-page results are answered with JSON like interface routes.
type Renderer interface {
	NotFound(c *tifa.Ctx) error
	Error(c *tifa.Ctx, e tifa.Error) error
}

type Server struct {
	Renderer Renderer
	cfg      config.Server
	hooks    Hooks
	mux      *http.ServeMux
	routes   map[string]map[string]func(*tifa.Ctx) error // path, then method
}

func New(cfg config.Config, hooks Hooks) *Server {
	s := &Server{cfg: cfg.Server, hooks: hooks, mux: http.NewServeMux(), routes: map[string]map[string]func(*tifa.Ctx) error{}}
	s.mux.Handle("/", routeHandler{s: s})
	return s
}

var methods = []string{"GET", "POST", "PUT", "PATCH", "DELETE"}

// Handle registers the OnXxx function of a route. The path is registered once without a method,
// so OnRequest runs with the matched pattern even when the method has no handler.
// Like http.ServeMux, it panics on invalid or conflicting registrations.
func (s *Server) Handle(method, path string, h func(*tifa.Ctx) error) {
	if !slices.Contains(methods, method) {
		panic(fmt.Sprintf("tifa: unsupported method %q for %s", method, path))
	}
	route, ok := s.routes[path]
	if !ok {
		route = map[string]func(*tifa.Ctx) error{}
		s.routes[path] = route
		pattern := path
		if path == "/" {
			pattern = "/{$}" // Path "/" is the exact home page, "/" in ServeMux would match every URL
		}
		s.mux.Handle(pattern, routeHandler{s: s, pattern: path, methods: route})
	}
	if route[method] != nil {
		panic(fmt.Sprintf("tifa: %s %s registered twice", method, path))
	}
	route[method] = h
}

// routeHandler is what the server registers in its ServeMux. methods is nil for the catch-all of unmatched URLs.
type routeHandler struct {
	s       *Server
	pattern string
	methods map[string]func(*tifa.Ctx) error
}

func (h routeHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.s.serve(w, r, h.pattern, func(c *tifa.Ctx) error {
		if h.methods == nil {
			return tifa.ErrNotFound
		}
		handle := h.methods[r.Method]
		if handle == nil && r.Method == "HEAD" {
			handle = h.methods["GET"]
		}
		if handle == nil {
			methodNotAllowed(c.Writer(), h.methods)
			return nil
		}
		return recovered(func() error { return handle(c) })
	})
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("X-Content-Type-Options", "nosniff")
	h, _ := s.mux.Handler(r)
	if _, ok := h.(routeHandler); ok {
		s.mux.ServeHTTP(w, r)
		return
	}
	// ServeMux answers a non-canonical path (double slash, dot segment, missing trailing slash)
	// with its own redirect. Record that redirect and hand it to OnRequest as the result of Next.
	probe := &redirectProbe{header: http.Header{}}
	h.ServeHTTP(probe, r)
	redirect := &core.RedirectError{URL: probe.header.Get("Location"), Code: probe.code}
	s.serve(w, r, "", func(*tifa.Ctx) error {
		if redirect.Code < 300 || redirect.Code > 399 || redirect.URL == "" {
			return fmt.Errorf("tifa: unexpected ServeMux response %d for %s", probe.code, r.URL.Path)
		}
		return redirect
	})
}

// redirectProbe captures the status and headers of a ServeMux internal handler and drops its body.
type redirectProbe struct {
	header http.Header
	code   int
}

func (p *redirectProbe) Header() http.Header         { return p.header }
func (p *redirectProbe) WriteHeader(code int)        { p.code = code }
func (p *redirectProbe) Write(b []byte) (int, error) { return len(b), nil }

// serve runs one request: OnRequest around route, then the error flow. pattern is empty when no route matched.
func (s *Server) serve(w http.ResponseWriter, r *http.Request, pattern string, route func(*tifa.Ctx) error) {
	tw := &writer{ResponseWriter: w}
	c := core.New(tw, r, pattern, s.cfg.BodyLimit)
	defer func() {
		if err := core.Finish(c); err != nil {
			log.Printf("tifa: %s %s: %v", r.Method, r.URL.Path, err)
		}
	}()
	var err error
	if s.hooks.OnRequest == nil {
		err = route(c)
	} else {
		core.SetNext(c, func() error { return route(c) })
		err = recovered(func() error { return s.hooks.OnRequest(c) })
	}
	if err != nil {
		page := pattern == "" && s.Renderer != nil && (r.Method == "GET" || r.Method == "HEAD") && !c.IsData()
		s.fail(c, tw, err, page)
	}
}

// fail turns an error into a response. Redirects, ErrNotFound and tifa.Error are expected results and skip OnError.
func (s *Server) fail(c *tifa.Ctx, w *writer, err error, page bool) {
	r := c.Request()
	var redirect *core.RedirectError
	var e tifa.Error
	switch {
	case errors.As(err, &redirect):
		if w.wrote {
			log.Printf("tifa: %s %s: redirect to %s after the response was written", r.Method, r.URL.Path, redirect.URL)
			return
		}
		http.Redirect(w, r, redirect.URL, redirect.Code)
		return
	case errors.Is(err, tifa.ErrNotFound):
		e = tifa.Error{Status: http.StatusNotFound, Message: http.StatusText(http.StatusNotFound)}
	case errors.As(err, &e) && validStatus(e.Status):
		if e.Message == "" {
			e.Message = http.StatusText(e.Status)
		}
	default:
		e = s.publicError(c, err)
	}
	if w.wrote {
		log.Printf("tifa: %s %s: %v after the response was written", r.Method, r.URL.Path, err)
		return
	}
	var renderErr error
	switch {
	case page && e.Status == http.StatusNotFound:
		renderErr = s.Renderer.NotFound(c)
	case page:
		renderErr = s.Renderer.Error(c, e)
	default:
		writeJSON(w, e.Status, map[string]string{"error": e.Message})
	}
	if renderErr != nil {
		log.Printf("tifa: %s %s: render %d page: %v", r.Method, r.URL.Path, e.Status, renderErr)
		if !w.wrote {
			writeJSON(w, e.Status, map[string]string{"error": e.Message})
		}
	}
}

// publicError asks OnError what to show for an unexpected error. Without OnError it logs the error and answers 500.
func (s *Server) publicError(c *tifa.Ctx, err error) tifa.Error {
	if s.hooks.OnError == nil {
		log.Printf("tifa: %s %s: %v", c.Request().Method, c.Request().URL.Path, err)
		return tifa.Error{Status: http.StatusInternalServerError, Message: http.StatusText(http.StatusInternalServerError)}
	}
	e := s.hooks.OnError(c, err)
	if !validStatus(e.Status) {
		e.Status = http.StatusInternalServerError
	}
	if e.Message == "" {
		e.Message = http.StatusText(e.Status)
	}
	return e
}

// validStatus reports whether a tifa.Error status can be sent as an error response.
// A tifa.Error with any other status is a bug in the code that built it, so it is handled as unexpected.
func validStatus(status int) bool { return status >= 400 && status <= 599 }

func methodNotAllowed(w http.ResponseWriter, route map[string]func(*tifa.Ctx) error) {
	var allow []string
	for _, m := range methods {
		if route[m] != nil {
			allow = append(allow, m)
			if m == "GET" {
				allow = append(allow, "HEAD")
			}
		}
	}
	w.Header().Set("Allow", strings.Join(allow, ", "))
	writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": http.StatusText(http.StatusMethodNotAllowed)})
}

// recovered turns a panic into an error so it follows the same flow as returned errors.
func recovered(f func() error) (err error) {
	defer func() {
		if p := recover(); p != nil {
			if p == http.ErrAbortHandler {
				panic(p)
			}
			err = fmt.Errorf("tifa: panic: %v\n%s", p, debug.Stack())
		}
	}()
	return f()
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		http.Error(w, "JSON encoding failed", 500)
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_, _ = w.Write(data)
}

// writer records whether the response has started, so a late error does not write a second one.
type writer struct {
	http.ResponseWriter
	wrote bool
}

// WriteHeader counts only final statuses. Like net/http, 1xx other than 101 is informational and may precede the real response.
func (w *writer) WriteHeader(code int) {
	if code < 100 || code > 199 || code == http.StatusSwitchingProtocols {
		w.wrote = true
	}
	w.ResponseWriter.WriteHeader(code)
}

func (w *writer) Write(b []byte) (int, error) {
	w.wrote = true
	return w.ResponseWriter.Write(b)
}

func (w *writer) Unwrap() http.ResponseWriter { return w.ResponseWriter }

// Run calls OnStart, listens on the configured address and serves until ctx is done.
func (s *Server) Run(ctx context.Context) error {
	if s.hooks.OnStart != nil {
		if err := s.hooks.OnStart(); err != nil {
			return fmt.Errorf("tifa: OnStart: %w", err)
		}
	}
	ln, err := net.Listen("tcp", s.cfg.Addr)
	if err != nil {
		return err
	}
	log.Printf("tifa: listening on http://%s", ln.Addr())
	return s.Serve(ctx, ln)
}

// Serve serves on ln until ctx is done, then stops taking requests and waits for in-flight ones.
// Requests still running after shutdown_timeout get their contexts canceled and their connections closed,
// and their handlers get one more shutdown_timeout to return. OnShutdown runs only after every handler
// has returned, with its own shutdown_timeout. If a handler never returns, OnShutdown is skipped and
// Serve reports it, because cleaning up under a running handler is worse than not cleaning up.
func (s *Server) Serve(ctx context.Context, ln net.Listener) error {
	var handlers sync.WaitGroup
	base, cancelRequests := context.WithCancel(context.Background())
	defer cancelRequests()
	srv := &http.Server{
		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			handlers.Add(1)
			defer handlers.Done()
			s.ServeHTTP(w, r)
		}),
		BaseContext:       func(net.Listener) context.Context { return base },
		ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second, WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second,
	}
	served := make(chan error, 1)
	go func() { served <- srv.Serve(ln) }()
	select {
	case err := <-served:
		return err
	case <-ctx.Done():
	}
	drain, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
	err := srv.Shutdown(drain)
	cancel()
	if err != nil {
		err = fmt.Errorf("tifa: waiting for in-flight requests: %w", err)
		cancelRequests()
		_ = srv.Close()
	}
	<-served
	returned := make(chan struct{})
	go func() {
		handlers.Wait()
		close(returned)
	}()
	select {
	case <-returned:
	case <-time.After(s.cfg.ShutdownTimeout):
		return errors.Join(err, errors.New("tifa: handlers still running after shutdown, OnShutdown skipped"))
	}
	if s.hooks.OnShutdown != nil {
		hookCtx, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
		defer cancel()
		if hookErr := s.hooks.OnShutdown(hookCtx); hookErr != nil {
			err = errors.Join(err, fmt.Errorf("tifa: OnShutdown: %w", hookErr))
		}
	}
	return err
}
